    $response = $renderer->render($e, $request);

    return (string) $response?->getContent();
};

$probe = static function (string $message, array $details) {
    return new class($message, $details) extends VaulterException implements ProblemException {
        use ProvidesProblemDetails;

        public function __construct(string $message, private array $details)
        {
            parent::__construct($message);
        }

        public function problemCode(): string
        {
            return 'concurrent_update';
        }

        public function httpStatus(): int
        {
            return 409;
        }

        public function problemDetails(): array
        {
            return $this->details;
        }
    };
};

$walk = static function (mixed $value) use (&$walk): array {
    if (is_string($value)) {
        return [$value];
    }
    if (!is_array($value)) {
        return [];
    }
    $out = [];
    foreach ($value as $k => $v) {
        if (is_string($k)) {
            $out[] = 'KEY:'.$k;
        }
        foreach ($walk($v) as $s) {
            $out[] = $s;
        }
    }

    return $out;
};

