$throw = static function (string $key, Closure $make): array {
    return [$key => static function () use ($make): never {
        try {
            $made = $make();
        } catch (Throwable $e) {
            throw $e;
        }
        if ($made instanceof Throwable) {
            throw $made;
        }
        throw new LogicException('probe did not throw');
    }];
};

