use Symfony\Component\HttpKernel\Exception\HttpException;
use Vaulter\Exceptions\Webhooks\BlockedOutboundUrlException;
use Vaulter\Tests\Support\ProblemProbeRoutes;
use Vaulter\Tests\TestCase;

final class P62HttpProbe extends TestCase
{
    public function test_probe(): void
    {
        $make = static function (Closure $factory): Closure {
            return static function () use ($factory): never {
                $made = $factory();
                if ($made instanceof Throwable) {
                    throw $made;
                }
                throw new LogicException('probe did not throw');
            };
        };

        ProblemProbeRoutes::register([
            'deny403' => $make(fn () => GateResponse::deny('hidden-gate-403')->withStatus(403)->authorize()),
            'deny404' => $make(fn () => GateResponse::deny('hidden-gate-404')->withStatus(404)->authorize()),
            'asnf' => $make(fn () => GateResponse::denyAsNotFound('hidden-as-not-found')->authorize()),
            'deny401' => $make(fn () => GateResponse::denyWithStatus(401, 'hidden-gate-401')->authorize()),
            'deny400' => $make(fn () => GateResponse::denyWithStatus(400, 'hidden-gate-400')->authorize()),
            'st403' => $make(fn () => (new AuthorizationException('hidden-with-403'))->withStatus(403)),
            'st404' => $make(fn () => (new AuthorizationException('hidden-with-404'))->withStatus(404)),
            'asnot' => $make(fn () => (new AuthorizationException('hidden-asnotfound'))->asNotFound()),
            'none' => $make(fn () => new AuthorizationException('hidden-nostatus')),
            'plain' => $make(fn () => new HttpException(403, 'plain-abort-403')),
            'blocked' => $make(fn () => BlockedOutboundUrlException::blockedAddress('metadata.google.internal', '169.254.169.254')),
        ]);

        foreach (['deny403','deny404','asnf','deny401','deny400','st403','st404','asnot','none','plain','blocked'] as $key) {
            $response = $this->getJson(ProblemProbeRoutes::path($key));
            $json = $response->json();
            $flat = json_encode($json);
            $needles = ['hidden-gate-403','hidden-gate-404','hidden-as-not-found','hidden-gate-401','hidden-gate-400','hidden-with-403','hidden-with-404','hidden-asnotfound','hidden-nostatus','plain-abort-403','metadata.google.internal','169.254.169.254','[Vaulter]'];
            $leaks = [];
            foreach ($needles as $needle) {
                if (is_string($flat) && str_contains($flat, $needle)) {
                    $leaks[] = $needle;
                }
            }
            echo $key
                .' http='.$response->getStatusCode()
                .' code='.($json['code'] ?? '?')
                .' status='.($json['status'] ?? '?')
                .' type='.$response->headers->get('Content-Type')
                .' leaks='.($leaks === [] ? 'none' : implode(',', $leaks))
                .' errors='.json_encode($json['errors'] ?? null)
                .' meta='.json_encode($json['meta'] ?? null)
                ."\n";
        }
    }
}

$test = new P62HttpProbe('test_probe');
$setUp = new ReflectionMethod($test, 'setUp');
$setUp->invoke($test);
try {
    $test->test_probe();
} catch (Throwable $e) {
    echo 'PROBE_THREW '.$e::class.' '.$e->getMessage()."\n".$e->getTraceAsString()."\n";
} finally {
    $tear = new ReflectionMethod($test, 'tearDown');
    $tear->invoke($test);
}
